  var m = s.match(/^<td([^>]*)>([\s\S]*)<\/td>$/i);
  return m ? { attrs: m[1], inner: m[2] } : { attrs: '', inner: s };
}
function _opsTdInner(html) {
  return _opsTdUnwrap(html).inner;
}
