function _opsAttentionHtml() {
  var bits = [];
  var unassigned = 0;
  var sameNoTime = 0;
  var unk = 0;
  var noPeople = 0;
  var day = (typeof _opsCleanDayInfo === 'function')
    ? _opsCleanDayInfo()
    : { clean: [] };
  (day.clean || []).forEach(function (r) {
    var names = (typeof _opsCleanerList === 'function') ? _opsCleanerList(r) : [];
    if (!names.length) unassigned++;
  });
  (_opsRows || []).forEach(function (b) {
    var isSame = (typeof _opsHasArrival === 'function')
      ? _opsHasArrival(b)
      : !!(b && (b.isCheckinOnly || b.checkinSameDay === 'yes'));
    var isUnk = !b.isCheckinOnly && (b.checkinSameDay === 'unknown' || !b.checkinSameDay);
    if (isUnk) unk++;
    if (isSame && !String(b.arrivalTime || '').trim()) sameNoTime++;
    if (isSame && (b.people == null || String(b.people).trim() === '')) noPeople++;
  });
  var off = {};
  if (typeof _opsNamesInDailyBlock === 'function') {
    _opsNamesInDailyBlock('repo').forEach(function (n) {
      off[(typeof _opsNormCleanerName === 'function') ? _opsNormCleanerName(n) : String(n || '').toLowerCase()] = 'ρεπό';
    });
    _opsNamesInDailyBlock('adeies').forEach(function (n) {
      off[(typeof _opsNormCleanerName === 'function') ? _opsNormCleanerName(n) : String(n || '').toLowerCase()] = 'άδεια';
    });
  }
  var conflicts = [];
  (day.clean || []).forEach(function (r) {
    var names = (typeof _opsCleanerList === 'function') ? _opsCleanerList(r) : [];
    names.forEach(function (n) {
      var k = (typeof _opsNormCleanerName === 'function') ? _opsNormCleanerName(n) : String(n || '').toLowerCase();
      if (off[k]) conflicts.push(n + ' (' + off[k] + ')');
    });
  });
  if (unassigned) bits.push(unassigned + ' unassigned');
  if (sameNoTime) bits.push(sameNoTime + ' same-day missing time');
  if (unk) bits.push(unk + ' unknown CI');
  if (noPeople) bits.push(noPeople + ' missing people');
  if (conflicts.length) bits.push('off-duty: ' + conflicts.join(', '));
  if (!bits.length) return '';
  return '<div class="opsx-attn">' + bits.map(function (t) {
    return '<span>' + _opsEscHtml(t) + '</span>';
  }).join('') + '</div>';
}

